<?php
use EIPSI\ExternalApi as A;
d2_case('50k scientific rows use bounded materialization and repeatable complete download',function(){global$wpdb;
 $study='STUDY_PERF_'.bin2hex(random_bytes(8));$public='PUBLIC_PERF_'.bin2hex(random_bytes(8));$questions=array();for($i=0;$i<200;$i++)$questions[]=pe_question('perf'.$i);
 $d=(new EIPSI\StudyEngine\Content\TemplateAdapter())->fromBlocks(array(pe_block('eipsi/form-container',array(),$questions)),$study,$public,1,array());$p=d2_publish(false,$d);
 for($i=0;$i<250;$i++){$answers=array();for($j=0;$j<200;$j++)$answers['R_perf'.$j]='synthetic-'.$i.'-'.$j;$f=pe_runtime()->handle($public);$done=pe_runtime()->handle($public,$f['token'],pe_request($f,'submit',$answers));d2_assert($done['view']['next_action']['kind']==='FINISHED');}
 $k=d2_key(array($study));$api=new A\DatasetSnapshots();$storage=new A\ExportStorage();memory_reset_peak_usage();$mem=memory_get_usage();$queries=$wpdb->num_queries;$start=microtime(true);$r=$api->create($k['principal'],$public,array('format'=>'csv'));$manifestMs=(microtime(true)-$start)*1000;$manifestQueries=$wpdb->num_queries-$queries;$start=microtime(true);$steps=0;
 while(($raw=$storage->get($r['export_id']))['state']==='PREPARING'){d2_assert(++$steps<1000);$api->work($r['export_id']);}
 $seconds=microtime(true)-$start;$peak=memory_get_peak_usage()-$mem;$ready=$api->status($k['principal'],$r['export_id']);d2_assert($ready['status']==='READY'&&$ready['row_count']===50000,'Performance export not READY with 50k rows');
 $start=microtime(true);$download=$api->download($k['principal'],$r['export_id']);$hash=hash_init('sha256');$bytes=0;while(!feof($download->stream)){$part=fread($download->stream,65536);hash_update($hash,$part);$bytes+=strlen($part);}$downloadSeconds=microtime(true)-$start;rewind($download->stream);$header=fgetcsv($download->stream,0,',','"','');d2_assert($header===array_merge(array('study_code'),EIPSI\StudyEngine\Management\ScientificDatasetOwner::COLUMNS));$csvRows=0;while(($row=fgetcsv($download->stream,0,',','"',''))!==false){d2_assert(count($row)===count($header));$csvRows++;}$download->close();d2_assert($csvRows===50000);$manifest=$api->manifest($k['principal'],$r['export_id']);d2_assert($bytes===$manifest['byte_count']&&hash_final($hash)===$manifest['sha256']&&$peak<67108864);
 $start=microtime(true);$cleaned=$storage->cleanup(time()+A\ExportStorage::TTL+301,50);$cleanupMs=(microtime(true)-$start)*1000;
 $metrics=array('synthetic_fixture'=>true,'rows'=>50000,'participants'=>250,'questions'=>200,'verified_csv_rows'=>$csvRows,'manifest_ms'=>round($manifestMs,3),'manifest_queries'=>$manifestQueries,'worker_seconds'=>round($seconds,3),'worker_steps'=>$steps,'rows_per_second'=>round(50000/$seconds,2),'incremental_peak_bytes'=>$peak,'artifact_bytes'=>$bytes,'download_seconds'=>round($downloadSeconds,3),'download_bytes_per_second'=>round($bytes/$downloadSeconds),'cleanup_ms'=>round($cleanupMs,3),'cleaned_exports'=>$cleaned);
 echo 'API2B_50K_METRIC '.json_encode($metrics)."\n";file_put_contents('/tmp/eipsi-api2b-50k.json',json_encode($metrics,JSON_PRETTY_PRINT));
});
